/**
 * Graphics & icon library (A4): pulls open-licence vector sets from npm (exact, pinned versions) and writes one sanitised SVG
 * per graphic plus a searchable manifest to fixtures/graphics/ (gitignored payload, like fixtures/emoji/).
 *
 *   Icons:        Lucide (ISC) · Tabler Icons outline + filled (MIT) · Phosphor regular/fill/duotone (MIT)
 *   Illustrations: Gravity UI illustrations (MIT, light theme)
 *   Graphics:     Pinselo originals (CC0-1.0), generated by tools/scripts/graphics/originals.ts
 *
 * Brand/logo icons are skipped (trademarks are not covered by the code licences).
 */
import { createHash } from 'node:crypto';
import { execFileSync, spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { originalGraphics } from './graphics/originals';

const ROOT = resolve(import.meta.dirname, '../..');
const TARGET = resolve(ROOT, process.env.OC_DEV_TARGET_DIR || 'target/dev');
const OUT = join(ROOT, 'fixtures/graphics');
const tmp = mkdtempSync(join(tmpdir(), 'oc-graphics-'));

/** Pinned packages (each published at least two weeks before it was pinned). */
const PKGS = {
  lucide: 'lucide-static@1.48.0',
  tabler: '@tabler/icons@3.48.0',
  phosphor: '@phosphor-icons/core@2.1.1',
  gravity: '@gravity-ui/illustrations@2.1.1',
} as const;

function unpack(pkg: string): string {
  const dir = join(tmp, pkg.replace(/[@/]/g, '_'));
  mkdirSync(dir, { recursive: true });
  const tgz = execFileSync('npm', ['pack', pkg, '--silent', '--pack-destination', dir], { encoding: 'utf8' }).trim().split('\n').pop()!;
  execFileSync('tar', ['xzf', join(dir, tgz), '-C', dir]);
  return join(dir, 'package');
}

interface Item { id: string; set: string; style?: string; name: string; tags: string[]; license: string; viewBox: string; kind: 'icon' | 'graphic' }
interface SetInfo { id: string; label: string; kind: 'icon' | 'graphic'; license: string; licenseUrl: string; source: string; version?: string; count: number }

/** oc-schema's SVG sanitiser over the whole batch in one `oc-sanitize-svg` run (cargo, no WebAssembly build needed). */
function sanitizeAll(raws: string[]): string[] {
  const r = spawnSync('cargo', ['run', '-q', '--release', '-p', 'oc-schema', '--bin', 'oc-sanitize-svg'], {
    cwd: ROOT, input: JSON.stringify(raws), maxBuffer: 1 << 30, encoding: 'utf8', stdio: ['pipe', 'pipe', 'inherit'], env: { ...process.env, CARGO_TARGET_DIR: TARGET },
  });
  if (r.status !== 0) throw new Error(`oc-sanitize-svg failed (exit ${r.status})`);
  return JSON.parse(r.stdout) as string[];
}

/** Minify a sanitised SVG: no comments, classes or fixed size (the viewBox drives scaling), single-line markup. */
function clean(sanitized: string): { svg: string; viewBox: string } | null {
  let s = sanitized.replace(/<\?xml[^>]*\?>/g, '').trim();
  const open = /<svg\b[^>]*>/i.exec(s);
  if (!open) return null;
  const vb = /viewBox\s*=\s*["']([^"']+)["']/i.exec(open[0])?.[1] ?? (() => {
    const w = /\swidth\s*=\s*["']([\d.]+)/.exec(open[0])?.[1];
    const h = /\sheight\s*=\s*["']([\d.]+)/.exec(open[0])?.[1];
    return w && h ? `0 0 ${w} ${h}` : null;
  })();
  if (!vb) return null;
  let tag = open[0].replace(/\s(class|width|height|data-[\w-]+|id)\s*=\s*("[^"]*"|'[^']*')/gi, '').replace(/\s+/g, ' ').replace(/\s*>$/, '>');
  if (!/viewBox=/.test(tag)) tag = tag.replace(/<svg\b/i, `<svg viewBox="${vb}"`);
  if (!/xmlns=/.test(tag)) tag = tag.replace(/<svg\b/i, '<svg xmlns="http://www.w3.org/2000/svg"');
  s = s.replace(open[0], tag).replace(/\sclass\s*=\s*("[^"]*"|'[^']*')/gi, '').replace(/>\s+</g, '><').replace(/\s{2,}/g, ' ').replace(/\s+\/>/g, '/>');
  return { svg: s, viewBox: vb.trim().split(/[\s,]+/).map(Number).join(' ') };
}

const items: Item[] = [];
const sets: SetInfo[] = [];
const queued = new Set<string>();
const pending: Array<{ it: Omit<Item, 'viewBox'>; raw: string }> = [];

/** Queue a graphic; all are sanitised in one batch and written at the end (set counts are filled in then). */
function put(it: Omit<Item, 'viewBox'>, raw: string): void {
  if (queued.has(it.id) || !/^[a-z0-9]+(-[a-z0-9]+)*$/.test(it.id)) return;
  queued.add(it.id);
  pending.push({ it, raw });
}

const humanize = (slug: string) => slug.replace(/-/g, ' ');
const pkgVersion = (dir: string) => (JSON.parse(readFileSync(join(dir, 'package.json'), 'utf8')) as { version: string }).version;

rmSync(OUT, { recursive: true, force: true });
mkdirSync(join(OUT, 'svg'), { recursive: true });
const notices: string[] = [];

// ---------------------------------------------------------------- Pinselo originals (CC0)
{
  for (const g of originalGraphics()) if (put({ id: `oc-${g.slug}`, set: 'opencanvas', name: g.name, tags: g.tags, license: 'CC0-1.0', kind: 'graphic' }, g.svg));
  sets.push({ id: 'opencanvas', label: 'Pinselo graphics', kind: 'graphic', license: 'CC0-1.0', licenseUrl: 'https://creativecommons.org/publicdomain/zero/1.0/', source: 'https://github.com/opencanvas', count: 0 });
  notices.push('Pinselo graphics (oc-*): original artwork generated by tools/scripts/graphics/originals.ts, dedicated to the public domain (CC0 1.0).');
}

// ---------------------------------------------------------------- Gravity UI illustrations (MIT)
{
  const dir = unpack(PKGS.gravity);
  for (const f of readdirSync(join(dir, 'svgs')).filter((x) => x.endsWith('-light.svg')).sort()) {
    const slug = f.replace(/-light\.svg$/, '');
    if (put({ id: `gravity-${slug}`, set: 'gravity', name: humanize(slug), tags: ['illustration', 'isometric', ...slug.split('-')], license: 'MIT', kind: 'graphic' }, readFileSync(join(dir, 'svgs', f), 'utf8')));
  }
  sets.push({ id: 'gravity', label: 'Gravity UI illustrations', kind: 'graphic', license: 'MIT', licenseUrl: 'https://github.com/gravity-ui/illustrations/blob/main/LICENSE', source: 'https://github.com/gravity-ui/illustrations', version: pkgVersion(dir), count: 0 });
  writeFileSync(join(OUT, 'LICENSE-gravity-ui.txt'), readFileSync(join(dir, 'LICENSE'), 'utf8'));
  notices.push(`Gravity UI illustrations (gravity-*): ${PKGS.gravity}, MIT License, © YANDEX LLC. See LICENSE-gravity-ui.txt.`);
}

// ---------------------------------------------------------------- Lucide (ISC)
{
  const dir = unpack(PKGS.lucide);
  const tags = JSON.parse(readFileSync(join(dir, 'tags.json'), 'utf8')) as Record<string, string[]>;
  // lucide-static also ships alias files (identical drawings under old names): keep the canonical name only.
  const seen = new Map<string, string>();
  const files = readdirSync(join(dir, 'icons')).filter((f) => f.endsWith('.svg')).sort((a, b) => Number(!(a.slice(0, -4) in tags)) - Number(!(b.slice(0, -4) in tags)) || a.localeCompare(b));
  for (const f of files) {
    const name = f.slice(0, -4);
    const raw = readFileSync(join(dir, 'icons', f), 'utf8');
    const body = createHash('sha1').update(raw.replace(/<!--[\s\S]*?-->/g, '').replace(/\sclass="[^"]*"/g, '')).digest('hex');
    if (seen.has(body)) continue;
    seen.set(body, name);
    if (put({ id: `lucide-${name}`, set: 'lucide', name, tags: tags[name] ?? [], license: 'ISC', kind: 'icon' }, raw));
  }
  sets.push({ id: 'lucide', label: 'Lucide', kind: 'icon', license: 'ISC', licenseUrl: 'https://lucide.dev/license', source: 'https://lucide.dev', version: pkgVersion(dir), count: 0 });
  writeFileSync(join(OUT, 'LICENSE-lucide.txt'), readFileSync(join(dir, 'LICENSE'), 'utf8'));
  notices.push(`Lucide icons (lucide-*): ${PKGS.lucide}, ISC License, © Lucide Contributors. See LICENSE-lucide.txt.`);
}

// ---------------------------------------------------------------- Phosphor (MIT): regular, fill, duotone
{
  const dir = unpack(PKGS.phosphor);
  const mod = (await import(pathToFileURL(join(dir, 'dist/index.mjs')).href)) as { icons: Array<{ name: string; tags: string[]; categories: string[] }> };
  for (const ic of mod.icons) {
    if (ic.categories.includes('brands')) continue;
    for (const style of ['regular', 'fill', 'duotone'] as const) {
      const f = join(dir, 'assets', style, style === 'regular' ? `${ic.name}.svg` : `${ic.name}-${style}.svg`);
      if (!existsSync(f)) continue;
      if (put({ id: style === 'regular' ? `phosphor-${ic.name}` : `phosphor-${ic.name}-${style}`, set: 'phosphor', style, name: ic.name, tags: [...ic.tags, ...ic.categories], license: 'MIT', kind: 'icon' }, readFileSync(f, 'utf8')));
    }
  }
  sets.push({ id: 'phosphor', label: 'Phosphor', kind: 'icon', license: 'MIT', licenseUrl: 'https://github.com/phosphor-icons/core/blob/main/LICENSE', source: 'https://phosphoricons.com', version: pkgVersion(dir), count: 0 });
  writeFileSync(join(OUT, 'LICENSE-phosphor.txt'), readFileSync(join(dir, 'LICENSE'), 'utf8'));
  notices.push(`Phosphor icons (phosphor-*): ${PKGS.phosphor}, MIT License, © Phosphor Icons. See LICENSE-phosphor.txt.`);
}

// ---------------------------------------------------------------- Tabler (MIT): outline + filled
{
  const dir = unpack(PKGS.tabler);
  const meta = JSON.parse(readFileSync(join(dir, 'icons.json'), 'utf8')) as Record<string, { name: string; category: string; tags: Array<string | number>; styles: Record<string, unknown> }>;
  for (const ic of Object.values(meta)) {
    if (ic.category === 'Brand' || ic.name.startsWith('brand-')) continue;
    const tags = [...ic.tags.map(String), ...(ic.category ? [ic.category] : [])];
    for (const style of ['outline', 'filled'] as const) {
      const f = join(dir, 'icons', style, `${ic.name}.svg`);
      if (!existsSync(f)) continue;
      if (put({ id: style === 'outline' ? `tabler-${ic.name}` : `tabler-${ic.name}-filled`, set: 'tabler', style, name: ic.name, tags, license: 'MIT', kind: 'icon' }, readFileSync(f, 'utf8')));
    }
  }
  sets.push({ id: 'tabler', label: 'Tabler Icons', kind: 'icon', license: 'MIT', licenseUrl: 'https://github.com/tabler/tabler-icons/blob/main/LICENSE', source: 'https://tabler.io/icons', version: pkgVersion(dir), count: 0 });
  writeFileSync(join(OUT, 'LICENSE-tabler.txt'), readFileSync(join(dir, 'LICENSE'), 'utf8'));
  notices.push(`Tabler Icons (tabler-*): ${PKGS.tabler}, MIT License, © Paweł Kuna. See LICENSE-tabler.txt.`);
}

sanitizeAll(pending.map((p) => p.raw)).forEach((svg, i) => {
  const { it } = pending[i]!;
  const c = clean(svg);
  if (!c) return;
  writeFileSync(join(OUT, 'svg', `${it.id}.svg`), c.svg);
  items.push({ ...it, tags: [...new Set(it.tags.map((t) => String(t).toLowerCase().trim()).filter((t) => t && t !== '*new*' && t !== it.name))].slice(0, 16), viewBox: c.viewBox });
});
for (const set of sets) set.count = items.filter((i) => i.set === set.id).length;

writeFileSync(join(OUT, 'manifest.json'), JSON.stringify({ version: 1, generated: new Date().toISOString().slice(0, 10), sets, items }));
writeFileSync(join(OUT, 'NOTICE.txt'), `Pinselo graphics & icon library (fixtures/graphics), generated by \`pnpm graphics:sync\`.\nBrand/logo icons are excluded. Icon sets keep their original licences:\n\n${notices.map((n) => `- ${n}`).join('\n')}\n`);
rmSync(tmp, { recursive: true, force: true });
console.log(`Wrote ${items.length} graphics to fixtures/graphics (${sets.map((s) => `${s.id} ${s.count}`).join(', ')})`);
